import json
from report_base import Report,ROOT

def build():
 api=json.loads((ROOT/'evidence/api-results.json').read_text())
 units=json.loads((ROOT/'evidence/unit-results.json').read_text())
 browser=json.loads((ROOT/'evidence/browser-results.json').read_text())
 assert api['executed']==20 and api['failed']==api['errors']==0
 assert len(units)==10 and all(x['status']=='passed' for x in units)
 assert browser['executed']==13 and not browser['failed']
 r=Report(6,'ITSM-система автоматизации бизнес-процессов организации',
 'ITSM, Service Desk, каталог услуг, инцидент, PHP, MariaDB, Apache, UML, тестирование, ТехноСервис',
 'Объект разработки — управление ИТ-услугами ООО «ТехноСервис». Цель — реализовать клиент-серверную ITSM-систему с сообщениями, каталогом и Service Desk. Применены структурное моделирование, UML Use Case, ролевое разграничение доступа и автоматизированное тестирование. Реализовано веб-приложение Apache/PHP/MariaDB, сохранены исходные шесть услуг и их ресурсные зависимости. Выполнены 10 модульных, 20 проверок модулей через API и 13 браузерных проверок; все завершились успешно. Отчёт содержит реальные снимки интерфейса, сценарии и результаты текущего запуска. Система пригодна для учебной демонстрации. Промышленное развёртывание, интеграции с мониторингом и расчёт финансовых компенсаций не выполнялись.')
 r.heading('ВВЕДЕНИЕ',center=True)
 r.p('Цель работы — спроектировать, реализовать и проверить ITSM-систему с регистрацией и аутентификацией пользователей, обменом сообщениями, управлением каталогом и обработкой инцидентов. Состав функций и порядок отчётности определены методическими указаниями к работе №6 [1].')
 r.p('Организация и перечень услуг сохранены из первой практической [2]. Функциональные подразделения и должности соответствуют работе №2 [3], а конфигурационные единицы — сервисно-ресурсным моделям работы №3 [4]. SLA работы №4 [5] определяет приоритеты, сроки и статусы. IDEF0-модели работы №5 [6] показывают операции, часть которых автоматизируется в Service Desk.')
 r.p('Задачи: определить архитектуру и данные, реализовать три модуля и права трёх ролей, разработать Use Case, выполнить проверки и зафиксировать фактические результаты. Приложение создано на стеке из методички: Apache 2.4, PHP 8.4 и MariaDB 11.8. В отчёте отделены модульные проверки логики от проверок API с реальной базой и браузерных сценариев.')
 r.p('Исходный код, схема БД, тесты и результаты сохранены в репозитории. Все снимки получены из работающего приложения; они не являются макетами. Оформление выполнено по предоставленным рекомендациям ГОСТ [7].')
 r.heading('1 ВЫПОЛНЕНИЕ РАБОТЫ')
 r.sub('1.1 Концептуальная модель системы')
 r.figure(ROOT/'diagrams/png/itsm_concept.png','Концептуальная модель ITSM-системы')
 r.p('Пользователи взаимодействуют с браузерным клиентом. Apache обслуживает статические файлы и передаёт PHP-запросы по FastCGI. Серверная часть проверяет сессию, роль и входные данные, выполняет операции модулей через PDO [8] и сохраняет состояние в MariaDB [9]. Ответы API представлены JSON; обновление интерфейса выполняется JavaScript.')
 r.p('Входные данные — сведения пользователей и услуг, сообщения, описания инцидентов и ссылки на КЕ. Выходные — каталог, переписка, история обработки, сроки и статусы. Ресурсы — Linux, CPU, память и диск; нормативные документы — SLA и регламент, модели IDEF0 и сценарии тестирования. Внешние системы vSphere и Zabbix обозначают ресурсы предприятия и не устанавливаются как часть данного прототипа.')
 r.sub('1.2 Структура данных и связи',True)
 r.table('Таблицы реализованной базы данных',['Таблица','Основные данные','Связь и назначение'],[
 ['users','Имя, email, хеш пароля, роль','Учётные записи; email уникален'],
 ['services','Название, описание, линия, тариф, статус','Каталог шести услуг и добавляемые услуги'],
 ['cis','Название и тип конфигурационной единицы','Общий справочник ресурсов'],
 ['service_cis','service_id, ci_id','Связь многие-ко-многим услуги и КЕ'],
 ['service_links','service_id, dependency_id','Зависимость от поддерживающей услуги'],
 ['incidents','Услуга, автор, исполнитель, приоритет, статус, время, решение','Ссылка на услугу и пользователей'],
 ['incident_cis','incident_id, ci_id','Затронутые ресурсы обращения'],
 ['history','Инцидент, сотрудник, действие, время','Последовательный журнал обработки'],
 ['messages','Отправитель, получатель, текст, время','Личная переписка пользователей']],[3.6,6.1,6.8])
 r.p('Внешние ключи обеспечивают ссылочную целостность. Удаление услуги с обращениями запрещено: её можно перевести в архив, сохранив историю. При удалении неиспользуемой услуги очищаются её связи; составные первичные ключи не допускают повторяющихся связей. Учебная БД использует кодировку utf8mb4 и локальный Unix-сокет без сетевого порта.')
 r.p('Первичное заполнение читает data/services.json. Сохранены тарифы, vSphere, FlexLM/KMS, Ansible/SCCM, Zabbix/Prometheus, Veeam, базы данных, серверы и хранилища. Зависимости услуг дополняют исходные модели: аренда и администрирование используют мониторинг, копирование связано с администрированием. Инициализация не дублирует исходный каталог при повторном запуске.')
 r.sub('1.3 Аутентификация и роли',True)
 r.figure(ROOT/'evidence/report-images/01_login.png','Форма входа работающего приложения',10)
 r.p('Вход выполняется по email и паролю. Пароли хранятся как хеши, сессия получает новый идентификатор после аутентификации. В интерфейсе постоянно отображаются имя и роль. Сотрудник видит свои обращения, поддержка — общую очередь, администратор дополнительно управляет каталогом и ролями.')
